class AlignedReps:
    """ev1.Reps interface: every grid query gets its own aligned patch."""

    def __init__(self, model, aud, bt, stride, chunk=4):
        self.model, self.aud, self.bt, self.chunk = model, aud, bt, chunk
        self.offs = np.arange(0, bt.seg_len, stride)

    @torch.no_grad()
    def u(self, e0s):
        e0s = np.asarray(e0s); out = []; q = torch.tensor(self.offs, device=self.bt.dev)
        for k in range(0, len(e0s), self.chunk):
            e = torch.tensor(e0s[k:k + self.chunk], device=self.bt.dev)
            u = self.model(self.bt.windows(e, q[None].expand(len(e), -1)))
            out.append(u.reshape(len(e), len(self.offs), -1).float().cpu().numpy())
        return np.concatenate(out)

    va = DenseReps.va


def evaluate_aligned(b, model, head, bt, coh, calib, grid):
    from auditory_alignment import evaluate as ev1
    from auditory_alignment_v2 import evaluate as ev2
    orig = ev1.Reps
    ev1.Reps = lambda enc, aud, bt_, **kw: AlignedReps(model, aud, bt_, grid)
    try:
        return ev2.evaluate_continuous(b, model, head, bt, coh, calib, None)
    finally:
        ev1.Reps = orig
